#include <stdlib.h>
#include <pthread.h>

// Assuming Image and PixelChannels are defined elsewhere
// typedef struct Image Image;
// typedef struct PixelChannels PixelChannels;

PixelChannels **allocate_pixel_channels(const Image *images) {
    // Retrieve the maximum number of threads allowed by the system
    long max_threads = sysconf(_SC_THREAD_THREADS_MAX);
    if (max_threads == -1) {
        // Fallback to a safe default if system call fails
        max_threads = 1024;
    }

    // Determine the number of images
    int num_images = 0;
    while (images[num_images].width > 0 && images[num_images].height > 0) {
        num_images++;
    }

    // Allocate memory for the array of pixel channels
    PixelChannels **pixel_channels = malloc(num_images * sizeof(PixelChannels *));
    if (!pixel_channels) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < num_images; i++) {
        // Allocate memory for pixel channels for each image
        pixel_channels[i] = malloc(images[i].width * images[i].height * sizeof(PixelChannels));
        if (!pixel_channels[i]) {
            // Free previously allocated memory and return NULL
            for (int j = 0; j < i; j++) {
                free(pixel_channels[j]);
            }
            free(pixel_channels);
            return NULL;
        }

        // Initialize pixel channels for each image
        for (size_t j = 0; j < images[i].width * images[i].height; j++) {
            pixel_channels[i][j] = (PixelChannels){0}; // Assuming default initialization
        }
    }

    return pixel_channels;
}
